// ─── 4. SMALL REUSABLE COMPONENTS ──────────────────────────

function GradientText({ children }) {
  return (
    <span style={{ background: `linear-gradient(135deg, ${BRAND.primaryLight}, ${BRAND.accent})`, WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>
      {children}
    </span>
  );
}

function PrimaryButton({ children, large = false, onClick }) {
  const sizeClasses = large ? "px-8 py-4 text-lg" : "px-6 py-3 text-sm";
  return (
    <button
      onClick={onClick}
      className={`${sizeClasses} rounded-full font-semibold tracking-wide transition-all duration-300 hover:scale-105 hover:shadow-lg cursor-pointer border-none`}
      style={{ background: `linear-gradient(135deg, ${BRAND.primary}, ${BRAND.accent})`, color: BRAND.textPrimary, boxShadow: `0 4px 24px ${BRAND.primary}40` }}
    >
      {children}
    </button>
  );
}

function SectionHeading({ subtitle, title, description }) {
  return (
    <div className="text-center max-w-2xl mx-auto mb-16">
      <p className="text-sm font-semibold tracking-widest uppercase mb-4" style={{ color: BRAND.accent }}>{subtitle}</p>
      <h2 className="text-4xl font-bold mb-4" style={{ color: BRAND.textPrimary }}>{title}</h2>
      {description && <p className="text-lg" style={{ color: BRAND.textSecondary }}>{description}</p>}
    </div>
  );
}


// ─── 5. PAGE SECTIONS ───────────────────────────────────────

function Navbar() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 transition-all duration-300" style={{ background: scrolled ? `${BRAND.bgDark}EE` : "transparent", backdropFilter: scrolled ? "blur(20px)" : "none", borderBottom: scrolled ? `1px solid ${BRAND.border}` : "none" }}>
      <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
        <a href="#" className="flex items-center gap-2 no-underline">
          <IconZap size={24} color={BRAND.accent} />
          <span className="text-xl font-bold tracking-tight" style={{ color: BRAND.textPrimary }}>Pop<GradientText>Feed</GradientText></span>
        </a>

        <div className="hidden md:flex items-center gap-8">
          {NAV_LINKS.map((link) => (
            <a key={link.label} href={link.href} className="text-sm font-medium no-underline transition-colors duration-200 hover:opacity-80" style={{ color: BRAND.textSecondary }}>{link.label}</a>
          ))}
          <PrimaryButton>Get Started Free</PrimaryButton>
        </div>

        <button className="md:hidden cursor-pointer bg-transparent border-none p-0" onClick={() => setMobileOpen(!mobileOpen)}>
          {mobileOpen ? <IconX size={24} color={BRAND.textPrimary} /> : <IconMenu size={24} color={BRAND.textPrimary} />}
        </button>
      </div>

      {mobileOpen && (
        <div className="md:hidden px-6 pb-6 flex flex-col gap-4" style={{ background: `${BRAND.bgDark}F5` }}>
          {NAV_LINKS.map((link) => (
            <a key={link.label} href={link.href} onClick={() => setMobileOpen(false)} className="text-base py-2 no-underline" style={{ color: BRAND.textSecondary }}>{link.label}</a>
          ))}
          <PrimaryButton>Get Started Free</PrimaryButton>
        </div>
      )}
    </nav>
  );
}

